	private function getForm() {
		$jsonForm = require_once \Yii::$aliases["@app"]."/components/api/forms/EFinanceFormData.php";
		if (!$jsonForm) {
			return "Cant find form";
		}
		$html = "";
		$html .= "<p class='lead'>Create loan</p>";
		$html  .= Html::beginForm("", "", ["id" => "efinance-form"]);
		$html  .= Html::input("hidden", "efinancePost", "true", ["class" => "form-control"]);
		$jsonForm = json_decode($jsonForm);
		foreach ($jsonForm->fields as $form) {
			$value = $this->getValue($form->name);
			if (property_exists ($form, "req")) {
				$req = ($value ? ["class" => "form-control", "required" => "required"] : ["class" => "form-control", "required" => "required"]);
			} else {
				$req = ($value ? ["class" => "form-control"] : ["class" => "form-control"]);
			}
			$html .= Html::label($form->name, null, ["class" => $this->getHtmlClass($form->name)]);
			if ($form->type == "select") {
				if ($form->name == "create_credit") {
					//$vals = apc_fetch("efin_vals");
					//if (!$vals) {
						$valueForm = [];
						foreach ($this->vals() as $val) {
							$valueForm[$val] = $val;
						}
						$html .= Html::tag("div", Html::dropDownList($form->name, $value, $valueForm, ["class" => "form-control", "required" => "required"]), ["class" => "form-group".$this->getHtmlClass($form->name)]);
						//apc_store("efin_vals", $html);
					//} else {
					//	$html .= $vals;
					//}
				} else {
					$html .= Html::tag("div", Html::dropDownList($form->name, $value, $form->values, $req), ["class" => "form-group".$this->getHtmlClass($form->name)]);
				}
			} elseif ($form->type == "checkbox") {
				$html .= Html::tag("div", Html::checkbox($form->name, $value, $req), ["class" => "form-group".$this->getHtmlClass($form->name)]);
			} else {
				$html .= Html::tag("div", Html::input("text", $form->name, $value, $req), ["class" => "form-group".$this->getHtmlClass($form->name)]);
			}
		}
		$html .= Html::label("Send latest bank account statement?");
		$html .= Html::tag("div", Html::checkbox("send-file", 1), ["class" => "form-group"]);
		$html .= Html::tag("div", Html::submitButton(\Yii::t('app/field', 'Post data'), ['class' => 'btn btn-primary btn-block', 'id' => 'efinance-post']), ["class" => "form-group"]);
		$html .= Html::endForm();
		$html .= Html::tag("div", "", ["id" => "efinance-api-info"]);
		
		// file upload form
		$html .= "<p class='lead'>Upload file</p>";
		$html .= Html::beginForm("", "", ["id" => "efinance-form-file", "enctype" => "multipart/form-data"]);
		$html .= Html::input("hidden", "efinancePostFile", "true", ["class" => "form-control"]);
		$html .= Html::input("file", "efinance-file", null, ["class" => "form-control mb5", "required" => "required"]);
		$html .= Html::tag("div", Html::submitButton(\Yii::t('app/field', 'Send file'), ['class' => 'btn btn-primary btn-block', 'id' => 'efinance-post-file']), ["class" => "form-group"]);
		$html .= Html::endForm();
		
		return $html;
	}
	
	private function getZip($address) {
		if (!$address) {
			return null;
		}
		return substr(strrchr($address, 'LV-'), 0, 7);
 	}
	
	private function getValue($formName) {
		switch ($formName) {
			case "person_code":
				return $this->getModel()->person->personal_code; break;
			case "address":
				return ($this->getModel()->extra ? $this->getModel()->extra->car_owner_address : null); break;
			case "workplace":
				return ($this->getModel()->extra ? $this->getModel()->extra->car_workplace : null); break;
			case "workplace_position":
				return ($this->getModel()->extra ? $this->getModel()->extra->car_position : null); break;
			case "zipcode":	
				return $this->getZip(($this->getModel()->extra ? $this->getModel()->extra->car_owner_address : null)); break;
			case "name":
				return $this->getModel()->person->name; break;
			case "surname":
				return $this->getModel()->person->surname; break;
			case "email":
				return $this->getModel()->person->email; break;
			case "mob_phone":
				return $this->getModel()->person->phone; break;
			case "salary_netto":
				return $this->getModel()->person->income; break;
			case "loan_monthly_payment":
				return 0; break;
			case "monthly_expenses":
				return $this->getModel()->person->outcome; break;
			case "source_of_income":
				return "Alga"; break;
			case "other_income":
				return 0; break;
			default:
