	private function _postFile() {
		return $this->_fileSendRequest();
	}
	
	private function _fileSendRequest($byPost = true) {
		$customerId = null;
		$personalCode = $this->getModel()->person->personal_code;
		
		$fields = [];
		$fields["login"] = \Yii::$app->params["efinanceapi_login"];
		$fields["pass"] = \Yii::$app->params["efinanceapi_pass"];
		
		$fieldsFull = $fields;
		
		$fields["data"] = json_encode([
				"person_code" => $personalCode
		]);
		
		//check if exists
		$ch = curl_init();
		curl_setopt($ch, CURLOPT_URL, \Yii::$app->params["efinanceapi_url_check"]);
		curl_setopt($ch, CURLOPT_RETURNTRANSFER, TRUE);
		curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 1);
		curl_setopt($ch, CURLOPT_POST,1);
		curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($fields));
		$result = curl_exec($ch);
		if ($result === false){
			$this->_log("CHECK REQUEST ERROR - ".curl_error($ch));
			echo "Error:" . curl_error($ch);
		} else {
			// if exists then credit only else full credit
			$this->_log("CHECK FILE REQUEST OK - REQUEST - ".http_build_query($fields)." - RESULT - ".$result);
			$clientList = json_decode($result, true);
		
			if (isset($clientList["customers"])) {
				foreach ($clientList["customers"] as $customer) {
					if ($personalCode == $customer["person_code"]) {
						$customerId = $customer["customer_id"];
						break;
					}
				}
			}
			
			if ($customerId) {
				// what file request type? true = using form file upload. false = on loan request create.
				if ($byPost) {
					$file = UploadedFile::getInstanceByName("efinance-file");
					$fields["data"] = json_encode([
							"customer_id" => $customerId,
							'file' => $file->name,
					]);
					$fields["file"] = new \CURLFile($file->tempName, $file->type, $file->name);
				} else {
					if ($this->getModel()->extra->bank_account_statement) {
						$fileName = $this->getModel()->extra->bank_account_statement;
						$savePath = "/tmp/".$fileName;
						
						if ($this->getModel()->source == "1lizings") {
							@file_put_contents($savePath, @file_get_contents("https://1lizings.lv/files/".$fileName));
						} else {
							@file_put_contents($savePath, @file_get_contents("https://www.onefinance.lv/statements/?f_name=".$fileName));
						}
						
						$fields["data"] = json_encode([
								"customer_id" => $customerId,
								'file' => $fileName,
						]);
						$fields["file"] = new \CURLFile($savePath, null, $fileName);
					} else {
						return;
					}
				}
		
				$ch2 = curl_init();
				curl_setopt($ch2, CURLOPT_URL, \Yii::$app->params["efinanceapi_url_file"]);
				curl_setopt($ch2, CURLOPT_RETURNTRANSFER, TRUE);
				curl_setopt($ch2, CURLOPT_SSL_VERIFYPEER, 1);
				curl_setopt($ch2, CURLOPT_POST,1);
				curl_setopt($ch2, CURLOPT_POSTFIELDS, $fields);
		
				$result2 = curl_exec($ch2);
		
				$resultArray = json_decode($result2, true);
				$this->_log("FILE REQUEST OK - REQUEST - ".http_build_query($fields)." - RESULT - ".$result2);
		
				if (isset($resultArray["ok"])) {
					\Yii::$app->getSession()->setFlash("success", \Yii::t("app/mail", "File sent!"));
				} else {
					\Yii::$app->getSession()->setFlash("danger", \Yii::t("app/mail", "File not sent! Error uploading file."));
				}
		
				curl_close($ch2);
			} else {
				\Yii::$app->getSession()->setFlash("danger", \Yii::t("app/mail", "File not sent! No customer found."));
			}
		}
		curl_close($ch);
	}
	
	private function _postData() {
		ob_end_clean();
		ob_start();
	
		$personalCode = null;
		$customerId = null;
		$fields = [];
		$fields["login"] = \Yii::$app->params["efinanceapi_login"];
		$fields["pass"] = \Yii::$app->params["efinanceapi_pass"];
		
		$fieldsFull = $fields;
		$fieldsCheck = $fields;
		$fieldsCredit = $fields;
		
		$tmpDataFull = [];
		$tmpDataCheck = [];
		$tmpDataCredit = [];
		foreach (\Yii::$app->getRequest()->post() as $key => $value) {
			if ($key !== "_csrf" && $key !== "efinancePost" && $key !== "send-file") {
				$tmpDataFull[$key] = $value;
				if ($key == "person_code") {
					$tmpDataCheck[$key] = $value;
					$personalCode = $value;
				}
				if ($key == "contract_id" || $key == "create_credit" || $key == "discount_code" || $key == "ip" || $key == "ref") {
					$tmpDataCredit[$key] = $value;
				}
			}
		}

		$fieldsFull["data"] = json_encode($tmpDataFull);
		$fieldsCheck["data"] = json_encode($tmpDataCheck);
		$fieldsCredit["data"] = $tmpDataCredit;
		
		//check if exists
		$ch = curl_init();
		curl_setopt($ch, CURLOPT_URL, \Yii::$app->params["efinanceapi_url_check"]);
		curl_setopt($ch, CURLOPT_RETURNTRANSFER, TRUE);
		curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 1);
		curl_setopt($ch, CURLOPT_POST,1);
		curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($fieldsCheck));
		$result = curl_exec($ch);
		if ($result === false){
			$this->_log("CHECK REQUEST ERROR - ".curl_error($ch));
			echo "Error:" . curl_error($ch);
		} else {
			// if exists then credit only else full credit
			$this->_log("CHECK REQUEST OK - REQUEST - ".http_build_query($fieldsCheck)." - RESULT - ".$result);
			$clientList = json_decode($result, true);
			
			if (isset($clientList["customers"])) {
				foreach ($clientList["customers"] as $customer) {
					if ($personalCode == $customer["person_code"]) {
						$customerId = $customer["customer_id"];
						break;
					}
				}
			}
			
			// create loan
			if (!$customerId) {
				$ch2 = curl_init();
				curl_setopt($ch2, CURLOPT_URL, \Yii::$app->params["efinanceapi_url"]);
				curl_setopt($ch2, CURLOPT_RETURNTRANSFER, TRUE);
				curl_setopt($ch2, CURLOPT_SSL_VERIFYPEER, 1);
				curl_setopt($ch2, CURLOPT_POST,1);
				curl_setopt($ch2, CURLOPT_POSTFIELDS, $fieldsFull);
				
				$result2 = curl_exec($ch2);
				$resultArray = json_decode($result2, true);
				$this->_log("FULL REQUEST OK - REQUEST - ".json_encode($fieldsFull)." - RESULT - ".$result2);
				
				if (isset($resultArray["ok"])) {
					echo "ok";
				} else {
					echo $resultArray["err"][0];
					$content = ob_get_contents();
					ob_end_clean();
					echo $content;
					\Yii::$app->end();
				}
				
				curl_close($ch2);
			} else {
				$ch2 = curl_init();
				$fieldsCredit["data"]["customer_id"] = $customerId;
				$fieldsCredit["data"] = json_encode($fieldsCredit["data"]);
				
				curl_setopt($ch2, CURLOPT_URL, \Yii::$app->params["efinanceapi_url2"]);
				curl_setopt($ch2, CURLOPT_RETURNTRANSFER, TRUE);
				curl_setopt($ch2, CURLOPT_SSL_VERIFYPEER, 1);
				curl_setopt($ch2, CURLOPT_POST,1);
				curl_setopt($ch2, CURLOPT_POSTFIELDS, http_build_query($fieldsCredit));
				
				$result2 = curl_exec($ch2);
				$resultArray = json_decode($result2, true);
				$this->_log("EXISTING  REQUEST OK - REQUEST - ".http_build_query($fieldsCredit)." - RESULT - ".$result2);
				
				if (isset($resultArray["ok"])) {
					echo "ok";
				} else {
					echo $resultArray["err"][0];
					$content = ob_get_contents();
					ob_end_clean();
					echo $content;
					\Yii::$app->end();
				}
				
				curl_close($ch2);
			}
		}
		curl_close($ch);
		
		// recheck customer id for contract_id save
		if (!$customerId) {
			$this->_log("NO CUSTOMER ID SO CHECK");
				
			$ch = curl_init();
			curl_setopt($ch, CURLOPT_URL, \Yii::$app->params["efinanceapi_url_check"]);
			curl_setopt($ch, CURLOPT_RETURNTRANSFER, TRUE);
			curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 1);
			curl_setopt($ch, CURLOPT_POST,1);
			curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($fieldsCheck));
			$result = curl_exec($ch);
			$clientList = json_decode($result, true);
				
			if (isset($clientList["customers"])) {
				foreach ($clientList["customers"] as $customer) {
					if ($personalCode == $customer["person_code"]) {
						$customerId = $customer["customer_id"];
						$this->_log("NO CUSTOMER ID SO CHECK FOUNC". $customerId);
						break;
					}
				}
			}
		}

		// save contract id
		if ($customerId) {
			$this->_log("CUSTOMER ID SO CHECK FOUND ". $customerId);
				
			$ch = curl_init();
			curl_setopt($ch, CURLOPT_URL, "http://e-finance.lv/api/v1.0/credits/banks?RPC=agents.getCustomerLoanList");
			curl_setopt($ch, CURLOPT_RETURNTRANSFER, TRUE);
			curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 1);
			curl_setopt($ch, CURLOPT_POST,1);
			curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
					"login" => \Yii::$app->params["efinanceapi_login"],
					"pass" => \Yii::$app->params["efinanceapi_pass"],
					"data" => json_encode([
							"customer_id" => $customerId
					])
			]));
			$result = curl_exec($ch);
			
			$this->_log("response ". $result);
				
			
			$clientList = json_decode($result, true);
			
			if (isset($clientList["customerLoans"])) {
				foreach ($clientList["customerLoans"] as $loan) {
					if (0 == $loan["c_confirmed"]) {
						$loanId = $loan["credit_id"];
						$this->_log("SETUP credit_id - ".$loanId);
						$this->_setContractId($loanId);
						$this->_log("CONTRACT ID SAVED". $loanId);
						break;
					}
				}
			}
		} ELSE {
			$this->_log("NO CUSTOMER ID SO NO CONTRAT ID SAVED");
		}

		
		$content = ob_get_contents();
		ob_end_clean();
		
		echo $content;
		
		if (\Yii::$app->getRequest()->post("send-file")) {
			$this->_fileSendRequest(false);
		}
		
		\Yii::$app->end();
	}
	
	private function _setContractId($id) {
		$this->_log("SET_CONTRACT_ID - CONTRACT_ID - ".$id." - MODEL_ID - ".$this->getModel()->id);
	
		\Yii::$app->db->createCommand("INSERT INTO `efinance_api` (`id`, `loan_id`, `contract_id`) VALUES (NULL, {$this->getModel()->id}, {$id});")->execute();
	}
	
	private function _getContractId() {
		if ($data = \Yii::$app->db->createCommand("SELECT *  FROM `efinance_api` WHERE `loan_id` = ".$this->getModel()->id)->queryOne()) {
			return $data["contract_id"];
		}
	
		return null;
	}
	
	private function _log($msg) {
		$fd = fopen(\Yii::$app->params["efinanceapi_log_path"], "a+");
		$str = "[" . date("Y/m/d h:i:s", time()) . "] " . $msg;
		fwrite($fd, $str . "\n");
		fclose($fd);
	}
